from rules import active_dependencies, allowed, is_acyclic


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])

    names = set(packages) | set(roots)
    for rows in packages.values():
        for row in rows:
            for dep in row.get('deps', []):
                names.add(dep['name'])
    names = sorted(names)

    initial = {name: [tuple(bounds)] for name, bounds in roots.items()}
    best_vector = None
    best_assignment = None

    def upper_bound(assigned, constraints):
        vector = []
        for name in names:
            if name in assigned:
                vector.append(assigned[name]['version'])
            elif name in constraints:
                rows = allowed(packages.get(name, []), name, constraints[name], blocked, pins)
                if not rows:
                    return None
                vector.append(max(row['version'] for row in rows))
            else:
                rows = allowed(packages.get(name, []), name, [], blocked, pins)
                vector.append(max([-1] + [row['version'] for row in rows]))
        return tuple(vector)

    def search(assigned, constraints):
        nonlocal best_vector, best_assignment

        for name, row in assigned.items():
            if name in constraints and not allowed([row], name, constraints[name], blocked, pins):
                return

        bound = upper_bound(assigned, constraints)
        if bound is None or (best_vector is not None and bound <= best_vector):
            return

        pending = [name for name in constraints if name not in assigned]
        if not pending:
            if is_acyclic(assigned, features):
                vector = tuple(assigned[name]['version'] if name in assigned else -1 for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_assignment = {name: row['version'] for name, row in assigned.items()}
            return

        choices = []
        for name in pending:
            rows = allowed(packages.get(name, []), name, constraints[name], blocked, pins)
            if not rows:
                return
            choices.append((len(rows), name, rows))
        _, name, rows = min(choices, key=lambda item: (item[0], item[1]))
        rows = sorted(rows, key=lambda row: row['version'], reverse=True)

        for row in rows:
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = {key: list(value) for key, value in constraints.items()}
            valid = True
            for dep in active_dependencies(row, features):
                target = dep['name']
                next_constraints.setdefault(target, []).append((dep['min'], dep['max']))
                if target in next_assigned and not allowed(
                    [next_assigned[target]], target, next_constraints[target], blocked, pins
                ):
                    valid = False
                    break
            if valid:
                search(next_assigned, next_constraints)

    search({}, initial)
    if best_assignment is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_assignment}

def active_dependencies(row, features):
    result = []
    for dep in row.get('deps', []):
        feature = dep.get('feature')
        if feature and feature not in features:
            continue
        result.append(dep)
    return result


def allowed(rows, name, constraints, blocked, pins):
    forbidden = blocked.get(name, [])
    result = []
    for row in rows:
        version = row['version']
        if version in forbidden:
            continue
        if name in pins and version != pins[name]:
            continue
        if all(low <= version <= high for low, high in constraints):
            result.append(row)
    return result


def is_acyclic(assigned, features):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dep in active_dependencies(assigned[name], features):
            target = dep['name']
            if target not in assigned or not visit(target):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in assigned)
